<style>
*,*::before,*::after{box-sizing:border-box;margin:0;padding:0}
:root{
  --blue:#3861FB;--navy:#0D1421;--gray:#808A9D;--gray-light:#C5CDD8;
  --bg:#fff;--bg-secondary:#F8FAFC;--bg-hover:#EFF2F5;--border:#E8ECF1;
  --green:#16c784;--red:#ea3943;--text:#0D1421;--text-secondary:#58667E;
  --font:'Inter',system-ui,-apple-system,sans-serif;
}
html{font-size:14px;-webkit-font-smoothing:antialiased}
body{font-family:var(--font);color:var(--text);background:var(--bg);line-height:1.5}
a{color:var(--blue);text-decoration:none}
a:hover{text-decoration:underline}
button{font-family:var(--font);cursor:pointer;border:none;background:none;font-size:inherit;color:inherit}
input{font-family:var(--font)}

/* Utility */
.tn{font-variant-numeric:tabular-nums;font-feature-settings:"tnum"}
.green{color:var(--green)}.red{color:var(--red)}.gray{color:var(--gray)}.blue{color:var(--blue)}

/* Header */
.site-header{background:var(--navy);padding:0 24px;height:56px;display:flex;align-items:center;gap:24px;position:sticky;top:0;z-index:100}
.logo{font-size:18px;font-weight:700;color:#fff;display:flex;align-items:center;gap:8px;white-space:nowrap}
.logo span{color:var(--blue)}
.nav-links{display:flex;gap:4px;flex:1}
.nav-links a{color:#CFD6E0;font-size:13px;font-weight:500;padding:6px 12px;border-radius:6px;transition:background .15s,color .15s}
.nav-links a:hover{background:rgba(255,255,255,.08);color:#fff;text-decoration:none}
.header-right{display:flex;align-items:center;gap:12px}
.search-box{display:flex;align-items:center;background:rgba(255,255,255,.08);border-radius:8px;padding:0 12px;height:36px;gap:8px;width:240px}
.search-box input{background:none;border:none;color:#fff;font-size:13px;outline:none;width:100%}
.search-box input::placeholder{color:rgba(255,255,255,.4)}
.search-box svg{color:rgba(255,255,255,.4);flex-shrink:0}
.btn-login{color:#CFD6E0;font-size:13px;font-weight:600;padding:8px 16px}
.btn-signup{background:var(--blue);color:#fff;font-size:13px;font-weight:600;padding:8px 16px;border-radius:8px}
.btn-signup:hover{background:#2b4fe0}

/* Top Bar Metrics */
.top-metrics{background:var(--bg-secondary);border-bottom:1px solid var(--border);padding:10px 24px;display:flex;align-items:center;gap:32px;flex-wrap:wrap}
.metric{display:flex;align-items:center;gap:6px;font-size:13px}
.metric-label{color:var(--text-secondary);font-weight:500}
.metric-value{font-weight:600}
.metric-change{font-size:12px;font-weight:600}
.metric-divider{width:1px;height:20px;background:var(--border)}
.fng-badge{display:inline-flex;align-items:center;gap:4px;background:#F0B93A1A;color:#C4960C;font-weight:600;font-size:12px;padding:2px 8px;border-radius:4px}

/* Promo Banner */
.promo-banner{background:linear-gradient(90deg,#1a1f35 0%,#0d1421 100%);padding:14px 24px;position:relative;overflow:hidden}
.promo-slides{display:flex;transition:transform .4s ease}
.promo-slide{min-width:100%;display:flex;align-items:center;justify-content:center;gap:16px;color:#fff;font-size:14px;font-weight:500}
.promo-slide .tag{background:var(--blue);color:#fff;font-size:11px;font-weight:700;padding:3px 8px;border-radius:4px;text-transform:uppercase;letter-spacing:.5px}
.promo-dots{display:flex;gap:6px;justify-content:center;margin-top:8px}
.promo-dot{width:6px;height:6px;border-radius:50%;background:rgba(255,255,255,.3);cursor:pointer}
.promo-dot.active{background:#fff}

/* AI Alerts */
.ai-bar{border-bottom:1px solid var(--border);padding:12px 24px;display:flex;align-items:center;gap:12px}
.ai-badge{background:linear-gradient(135deg,#8B5CF6,#6366F1);color:#fff;font-size:11px;font-weight:700;padding:3px 8px;border-radius:4px;white-space:nowrap}
.ai-prompt{font-size:13px;font-weight:500;color:var(--navy);flex-shrink:0}
.ai-chips{display:flex;gap:8px;overflow-x:auto;scrollbar-width:none;padding:2px 0}
.ai-chips::-webkit-scrollbar{display:none}
.ai-chip{font-size:12px;color:var(--blue);background:#3861FB0D;border:1px solid #3861FB26;padding:4px 12px;border-radius:20px;white-space:nowrap;cursor:pointer;transition:background .15s}
.ai-chip:hover{background:#3861FB1A}

/* Main Content Area */
.main{max-width:1440px;margin:0 auto;padding:0 24px}

/* Tabs Row */
.tabs-row{display:flex;align-items:center;gap:0;padding:16px 0 0;border-bottom:1px solid var(--border)}
.cat-tabs{display:flex;gap:0;flex:1;overflow-x:auto;scrollbar-width:none}
.cat-tabs::-webkit-scrollbar{display:none}
.cat-tab{font-size:13px;font-weight:600;color:var(--text-secondary);padding:10px 16px;border-bottom:2px solid transparent;white-space:nowrap;transition:color .15s,border-color .15s;cursor:pointer}
.cat-tab:hover{color:var(--text)}
.cat-tab.active{color:var(--blue);border-bottom-color:var(--blue)}

/* Network Filter */
.network-row{display:flex;align-items:center;gap:8px;padding:14px 0;overflow-x:auto;scrollbar-width:none}
.network-row::-webkit-scrollbar{display:none}
.net-tab{font-size:12px;font-weight:600;color:var(--text-secondary);padding:6px 14px;border-radius:8px;border:1px solid var(--border);white-space:nowrap;cursor:pointer;transition:all .15s}
.net-tab:hover{border-color:var(--blue);color:var(--blue)}
.net-tab.active{background:var(--blue);color:#fff;border-color:var(--blue)}

/* Table Controls */
.table-controls{display:flex;align-items:center;gap:8px;padding:8px 0;flex-wrap:wrap}
.tc-btn{font-size:12px;font-weight:600;color:var(--text-secondary);padding:6px 12px;border-radius:6px;border:1px solid var(--border);display:flex;align-items:center;gap:4px;cursor:pointer;transition:all .15s}
.tc-btn:hover{border-color:var(--blue);color:var(--blue)}
.tc-btn.active{background:var(--blue);color:#fff;border-color:var(--blue)}
.tc-btn svg{width:14px;height:14px}
.tc-sort{font-size:12px;font-weight:600;color:var(--text);display:flex;align-items:center;gap:4px;cursor:pointer}

/* Columns dropdown */
.columns-dropdown{position:absolute;top:100%;right:0;background:#fff;border:1px solid var(--border);border-radius:10px;box-shadow:0 8px 24px rgba(0,0,0,.12);padding:12px;z-index:50;min-width:200px;display:none}
.columns-dropdown.show{display:block}
.col-toggle{display:flex;align-items:center;gap:8px;padding:6px 0;font-size:13px;cursor:pointer}
.col-toggle input{accent-color:var(--blue);width:16px;height:16px}

/* Filters panel */
.filters-panel{background:var(--bg-secondary);border:1px solid var(--border);border-radius:10px;padding:16px;margin-bottom:12px;display:none}
.filters-panel.show{display:block}
.filter-row{display:flex;gap:12px;flex-wrap:wrap;align-items:end}
.filter-group{display:flex;flex-direction:column;gap:4px}
.filter-group label{font-size:11px;font-weight:600;color:var(--text-secondary);text-transform:uppercase;letter-spacing:.5px}
.filter-group select,.filter-group input{font-size:13px;padding:6px 10px;border:1px solid var(--border);border-radius:6px;outline:none;background:#fff}
.filter-group select:focus,.filter-group input:focus{border-color:var(--blue)}

/* Crypto Table */
.crypto-table-wrap{overflow-x:auto;border:1px solid var(--border);border-radius:10px;margin-bottom:4px}
.crypto-table{width:100%;border-collapse:collapse;min-width:1100px}
.crypto-table th{position:sticky;top:0;background:var(--bg-secondary);font-size:11px;font-weight:700;color:var(--text-secondary);text-transform:uppercase;letter-spacing:.5px;padding:10px 12px;text-align:left;border-bottom:1px solid var(--border);white-space:nowrap;user-select:none}
.crypto-table th.right,.crypto-table td.right{text-align:right}
.crypto-table th.sortable{cursor:pointer}
.crypto-table th.sortable:hover{color:var(--text)}
.crypto-table th .sort-icon{display:inline-block;margin-left:2px;opacity:.3;font-size:10px}
.crypto-table th.sorted .sort-icon{opacity:1;color:var(--blue)}
.crypto-table td{padding:10px 12px;border-bottom:1px solid var(--border);font-size:13px;white-space:nowrap;vertical-align:middle}
.crypto-table tbody tr{transition:background .1s}
.crypto-table tbody tr:hover{background:var(--bg-hover)}
.rank-cell{font-weight:600;color:var(--text-secondary);width:44px;text-align:center}
.name-cell{display:flex;align-items:center;gap:8px;min-width:160px}
.name-cell .icon{width:24px;height:24px;border-radius:50%;display:flex;align-items:center;justify-content:center;font-size:10px;font-weight:700;color:#fff;flex-shrink:0}
.name-cell .name{font-weight:600;color:var(--text)}
.name-cell .symbol{color:var(--text-secondary);font-size:12px}
.pct{font-weight:600;font-size:12px}
.sparkline{width:120px;height:36px}
.sparkline svg{width:100%;height:100%}
.index-row td{background:#3861FB08;font-weight:600}

/* Pagination */
.pagination{display:flex;align-items:center;justify-content:space-between;padding:16px 0;flex-wrap:wrap;gap:8px}
.page-info{font-size:13px;color:var(--text-secondary)}
.page-btns{display:flex;gap:4px}
.page-btn{width:36px;height:36px;display:flex;align-items:center;justify-content:center;border-radius:8px;font-size:13px;font-weight:600;color:var(--text-secondary);border:1px solid var(--border);cursor:pointer;transition:all .15s}
.page-btn:hover{border-color:var(--blue);color:var(--blue)}
.page-btn.active{background:var(--blue);color:#fff;border-color:var(--blue)}

/* Market Summary */
.market-summary{padding:32px 0;border-top:1px solid var(--border)}
.market-summary h2{font-size:20px;font-weight:700;margin-bottom:12px}
.market-summary p{font-size:14px;color:var(--text-secondary);line-height:1.7}
.market-summary p strong{color:var(--text)}
.read-more-btn{color:var(--blue);font-size:13px;font-weight:600;margin-top:8px;cursor:pointer;display:inline-flex;align-items:center;gap:4px}
.read-more-btn:hover{text-decoration:underline}
.more-content{display:none;margin-top:8px;font-size:14px;color:var(--text-secondary);line-height:1.7}
.more-content.show{display:block}

/* Info Content */
.info-content{padding:32px 0;border-top:1px solid var(--border)}
.info-content h2{font-size:20px;font-weight:700;margin-bottom:12px}
.info-content h3{font-size:16px;font-weight:600;margin:20px 0 8px}
.info-content p{font-size:14px;color:var(--text-secondary);line-height:1.7}

/* Footer */
.site-footer{background:var(--navy);color:#CFD6E0;padding:40px 24px 24px;margin-top:40px}
.footer-grid{max-width:1440px;margin:0 auto;display:grid;grid-template-columns:repeat(4,1fr);gap:32px}
.footer-col h4{color:#fff;font-size:14px;font-weight:700;margin-bottom:12px}
.footer-col a{display:block;font-size:13px;color:#808A9D;padding:3px 0}
.footer-col a:hover{color:#fff;text-decoration:none}
.footer-bottom{max-width:1440px;margin:24px auto 0;padding-top:16px;border-top:1px solid rgba(255,255,255,.08);font-size:12px;color:#808A9D}

/* Responsive */
@media(max-width:768px){
  .site-header{padding:0 12px;gap:12px}
  .nav-links{display:none}
  .search-box{width:160px}
  .top-metrics{padding:8px 12px;gap:16px;font-size:12px}
  .main{padding:0 12px}
  .footer-grid{grid-template-columns:repeat(2,1fr)}
}
</style>
</head>
