// === FORMATTERS ===
function fmtPrice(p){
  if(p>=1) return '$'+p.toLocaleString('en-US',{minimumFractionDigits:2,maximumFractionDigits:2});
  if(p>=.01) return '$'+p.toFixed(4);
  if(p>=.001) return '$'+p.toFixed(5);
  return '$'+p.toFixed(7);
}
function fmtMcap(v){
  if(v>=1e12) return '$'+(v/1e12).toFixed(2)+'T';
  if(v>=1e9) return '$'+(v/1e9).toFixed(2)+'B';
  if(v>=1e6) return '$'+(v/1e6).toFixed(2)+'M';
  return '$'+v.toLocaleString();
}
function fmtVol(v){
  if(v>=1e9) return '$'+(v/1e9).toFixed(2)+'B';
  if(v>=1e6) return '$'+(v/1e6).toFixed(2)+'M';
  return '$'+v.toLocaleString();
}
function fmtSupply(v,sym){
  if(v>=1e12) return (v/1e12).toFixed(2)+'T '+sym;
  if(v>=1e9) return (v/1e9).toFixed(2)+'B '+sym;
  if(v>=1e6) return (v/1e6).toFixed(2)+'M '+sym;
  return v.toLocaleString()+' '+sym;
}
function fmtPct(v){
  const cls=v>=0?'green':'red';
  const sign=v>=0?'+':'';
  return `<span class="pct ${cls} tn">${sign}${v.toFixed(2)}%</span>`;
}

// === SPARKLINE ===
function genSparkline(d7){
  // generate plausible sparkline data based on 7d trend
  const pts=[];
  let v=50+(Math.random()*20);
  const trend=d7>0?1:-1;
  for(let i=0;i<14;i++){
    v+=trend*(1+Math.random()*3)-1+Math.random()*2;
    v=Math.max(5,Math.min(95,v));
    pts.push(v);
  }
  return pts;
}
function sparklineSVG(pts, positive){
  const w=120,h=36,pad=2;
  const mn=Math.min(...pts),mx=Math.max(...pts),rng=mx-mn||1;
  const coords=pts.map((v,i)=>{
    const x=pad+i*(w-2*pad)/(pts.length-1);
    const y=h-pad-(v-mn)/rng*(h-2*pad);
    return `${x.toFixed(1)},${y.toFixed(1)}`;
  });
  const color=positive?'#16c784':'#ea3943';
  const fillId='g'+Math.random().toString(36).slice(2,8);
  return `<svg viewBox="0 0 ${w} ${h}" preserveAspectRatio="none">
    <defs><linearGradient id="${fillId}" x1="0" y1="0" x2="0" y2="1">
      <stop offset="0%" stop-color="${color}" stop-opacity="0.2"/>
      <stop offset="100%" stop-color="${color}" stop-opacity="0"/>
    </linearGradient></defs>
    <polygon points="${coords[0].split(',')[0]},${h} ${coords.join(' ')} ${coords[coords.length-1].split(',')[0]},${h}" fill="url(#${fillId})"/>
    <polyline points="${coords.join(' ')}" fill="none" stroke="${color}" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round"/>
  </svg>`;
}

