function renderTable(data){
  const tbody=document.getElementById('cryptoBody');
  // Index row first
  let html=`<tr class="index-row">
    <td class="right tn" style="width:44px"></td>
    <td><div class="name-cell"><div class="icon" style="background:var(--blue)">20</div><div><span class="name">CoinTracker 20 Index</span><br><span class="symbol">DTFCTP20</span></div></div></td>
